  var folioWords={prev:['Previous','上一页','上一頁','Anterior','Anterior'],next:['Next','下一页','下一頁','Siguiente','Següent'],open:['Open','打开','打開','Abrir','Obrir'],cover:['Cover','封面','封面','Portada','Portada'],private:['Family keepsake','家庭纪念物','屋企紀念物','Recuerdo familiar','Record familiar']};
  // Narrators own the recollections; formulas, quoted inscriptions and labels remain part of the object.
  var narratorNames={wei:['Wei','Wei','Wei','Wei','Wei'],mei:['Mei','Mei','Mei','Mei','Mei'],popo:['Popo','婆婆','婆婆','Popo','La Popo']};
  function narrator(id){return id==='physics-notebook'||id==='beijing-transit-card'?'wei':id==='fashion-sketchbook'?'mei':'popo';}
  function coverLine(item){
    if(item.id==='fashion-sketchbook')return tr(["not finished. don't judge the shoes.","还没画完。别评价那双鞋。","還沒畫完。別評價那雙鞋。","sin acabar. no juzgues los zapatos.","sense acabar. no jutgis les sabates."]);
    return tr(item.ui.line).replace(/^Wei\s*[:：]\s*/,'');
  }
